test('TC-001: Login with valid credentials', async ({ page }) => {
  await page.goto('https://example.com/login');
  await page.fill('#email', 'testuser@example.com');
  await page.fill('#password', 'SecurePass123!');
  await page.click('button[type="submit"]');
  await expect(page).toHaveURL('/dashboard');
  await expect(page.locator('h1')).toContainText('Welcome back');
});

test('TC-006: Payment form accepts valid card', async ({ page }) => {
  await page.goto('https://example.com/checkout/payment');
  await page.fill('#card-number', '4242 4242 4242 4242');
  await page.fill('#card-expiry', '12/26');
  await page.fill('#card-cvc', '123');
  await page.click('#pay-now-btn');
  await expect(page.locator('#confirmation-banner')).toBeVisible();
});
